'use client';

import { useEffect, useState } from 'react';
import { notFound } from 'next/navigation';
import { getSession, verifyAdmin } from '../lib/auth';

export default function AdminPage() {
  const [isAdmin, setIsAdmin] = useState<boolean | null>(null);
  const [session, setSession] = useState<any>(null);

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const sessionData = await getSession();
        const authResult = await verifyAdmin();

        setSession(sessionData);
        setIsAdmin(authResult.isAdmin);

        // If not admin, return 403 Forbidden using Next.js error boundary
        if (!authResult.isAdmin) {
          notFound(); // This will trigger the 404 page, but we need 403
        }
      } catch (error) {
        console.error('Auth check failed:', error);
        setIsAdmin(false);
      }
    };

    checkAuth();
  }, []);

  // Show loading state while checking authentication
  if (isAdmin === null) {
    return (
      <main className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-gray-900 mx-auto"></div>
          <p className="mt-4 text-gray-600">Checking permissions...</p>
        </div>
      </main>
    );
  }

  // Show admin dashboard if authenticated
  if (isAdmin) {
    return (
      <main className="min-h-screen bg-gray-50">
        <div className="container mx-auto px-4 py-8">
          <div className="bg-white rounded-lg shadow-lg p-6">
            <h1 className="text-3xl font-bold text-gray-900 mb-4">Admin Dashboard</h1>
            <p className="text-gray-600 mb-6">
              Welcome, {session?.name}! You have admin access to this area.
            </p>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                <h3 className="font-semibold text-blue-900">User Management</h3>
                <p className="text-blue-600 text-sm mt-2">Manage users and permissions</p>
              </div>

              <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                <h3 className="font-semibold text-green-900">System Settings</h3>
                <p className="text-green-600 text-sm mt-2">Configure application settings</p>
              </div>

              <div className="bg-purple-50 border border-purple-200 rounded-lg p-4">
                <h3 className="font-semibold text-purple-900">Analytics</h3>
                <p className="text-purple-600 text-sm mt-2">View usage statistics</p>
              </div>
            </div>
          </div>
        </div>
      </main>
    );
  }

  // This should not be reached due to notFound() above, but handle it just in case
  return null;
}

