'use client';

import { useEffect } from 'react';

export default function Forbidden() {
  useEffect(() => {
    // Set the proper 403 status code
    if (typeof window !== 'undefined') {
      // This won't actually change the HTTP status code in a client component,
      // but we can show a proper 403 error page
      document.title = '403 - Forbidden';
    }
  }, []);

  return (
    <main className="min-h-screen flex items-center justify-center bg-gray-50">
      <div className="max-w-md w-full bg-white rounded-lg shadow-lg p-8 text-center">
        <div className="mb-6">
          <div className="text-6xl font-bold text-red-600 mb-2">403</div>
          <h1 className="text-2xl font-semibold text-gray-900 mb-2">Forbidden</h1>
          <p className="text-gray-600">You don't have permission to access this resource.</p>
        </div>

        <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6">
          <p className="text-red-800 text-sm">
            This page requires admin privileges. Please contact your administrator if you believe this is an error.
          </p>
        </div>

        <div className="space-y-3">
          <button
            onClick={() => window.location.href = '/'}
            className="w-full bg-blue-600 text-white py-2 px-4 rounded-lg hover:bg-blue-700 transition-colors"
          >
            Return to Home
          </button>
          <button
            onClick={() => window.history.back()}
            className="w-full bg-gray-200 text-gray-800 py-2 px-4 rounded-lg hover:bg-gray-300 transition-colors"
          >
            Go Back
          </button>
        </div>

        <div className="mt-6 text-xs text-gray-500">
          <p>Access denied: Insufficient privileges</p>
        </div>
      </div>
    </main>
  );
}

